import java.util.*;
import java.io.*;

public class Main {
    static int SZ;
    static final long INF = Long.MAX_VALUE / 4;

    static long[][] mult(long[][] A, long[][] B) {
        long[][] C = new long[SZ][SZ];
        for (int i = 0; i < SZ; i++) Arrays.fill(C[i], INF);
        for (int i = 0; i < SZ; i++) {
            for (int k = 0; k < SZ; k++) {
                if (A[i][k] >= INF) continue;
                long aik = A[i][k];
                for (int j = 0; j < SZ; j++) {
                    if (B[k][j] >= INF) continue;
                    long v = aik + B[k][j];
                    if (v < C[i][j]) C[i][j] = v;
                }
            }
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int m = (int) in.nval;
        int[] a = new int[n], b = new int[n];
        for (int i = 0; i < n; i++) { in.nextToken(); a[i] = (int) in.nval; }
        for (int i = 0; i < n; i++) { in.nextToken(); b[i] = (int) in.nval; }

        SZ = n + 1;
        long[][] M = new long[SZ][SZ];
        for (int i = 0; i < SZ; i++) {
            Arrays.fill(M[i], INF);
            M[i][i] = 0;
        }
        for (int t = 0; t < n; t++) {
            long[][] T = new long[SZ][SZ];
            for (int i = 0; i < SZ; i++) Arrays.fill(T[i], INF);
            for (int i = 0; i < SZ; i++) {
                if (i + 1 < SZ) T[i][i + 1] = Math.min(T[i][i + 1], a[t]);
                if (i - 1 >= 0) T[i][i - 1] = Math.min(T[i][i - 1], b[t]);
            }
            M = mult(M, T);
        }

        long[][] res = new long[SZ][SZ];
        for (int i = 0; i < SZ; i++) {
            Arrays.fill(res[i], INF);
            res[i][i] = 0;
        }
        int e = m;
        long[][] base = M;
        while (e > 0) {
            if ((e & 1) == 1) res = mult(res, base);
            base = mult(base, base);
            e >>= 1;
        }
        System.out.println(res[0][0]);
    }
}
